use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{fs,fmt::Write,path::{Path,PathBuf},process::{Command,Stdio},collections::BTreeMap};
const R:&str="/home/ubuntu/src/zopro-perf-work/g2-fixed-wnaf176";const O:&str="/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-11-06-g2-fixed-wnaf176";
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}fn hash(b:&[u8])->String{format!("{:x}",Sha256::digest(b))}fn walk(p:&Path)->Vec<PathBuf>{let mut v=vec![];for e in fs::read_dir(p).unwrap(){let p=e.unwrap().path();if p.is_dir(){v.extend(walk(&p))}else{v.push(p)}}v.sort();v}
fn main(){let r=Path::new(R);let out=Path::new(O);assert!(!out.exists());assert_eq!(read(r.join("review.json"))["passed"],true);assert_eq!(read(r.join("analysis.json"))["necessary_native_selection_passed"],false);fs::create_dir_all(out.join("artifacts")).unwrap();let allowed=|p:&Path|matches!(p.extension().and_then(|s|s.to_str()),Some("rs"|"md"|"json"|"log"));let mut members=BTreeMap::new();for p in walk(r).into_iter().filter(|p|allowed(p)){let b=fs::read(&p).unwrap();let text=String::from_utf8(b.clone()).unwrap();assert_eq!(text.as_bytes(),b);members.insert(p.strip_prefix(r).unwrap().display().to_string(),json!({"utf8":text,"length":b.len(),"sha256":hash(&b)}));}
let encoded=serde_json::to_vec(&members).unwrap();let tmp=out.join("receipts.temporary");let gz=out.join("artifacts/receipts-and-helpers.json.gz");fs::write(&tmp,&encoded).unwrap();assert!(Command::new("gzip").args(["-n","-c"]).arg(&tmp).stdout(Stdio::from(fs::File::create(&gz).unwrap())).status().unwrap().success());let decoded=Command::new("gzip").args(["-d","-c"]).arg(&gz).output().unwrap();assert!(decoded.status.success());assert_eq!(decoded.stdout,encoded);let records:Value=serde_json::from_slice(&decoded.stdout).unwrap();for(_,v)in records.as_object().unwrap(){let b=v["utf8"].as_str().unwrap().as_bytes();assert_eq!(hash(b),v["sha256"]);assert_eq!(b.len(),v["length"].as_u64().unwrap()as usize);}fs::remove_file(tmp).unwrap();
for f in["analysis.json","review.json","design.md","count-protocol.md","algebra.rs","model.rs","original-booth.rs","split.rs","groups.rs","prepare.rs","prepare-count.rs","review.rs","publish.rs"]{fs::copy(r.join(f),out.join("artifacts").join(f)).unwrap();}fs::copy(r.join("report-draft.md"),out.join("README.md")).unwrap();let record=json!({"receipt_and_helper_members":members.len(),"gzip_and_UTF8_member_hash_roundtrip_verified":true,"no_runtime_snapshot_or_binary_or_private_data_exported":true,"no_capture_or_test_rerun":true,"workflow_commands":6,"new_proofs":0});fs::write(out.join("artifacts/publication.json"),serde_json::to_vec_pretty(&record).unwrap()).unwrap();let mut sums=String::new();let files=walk(out);for p in&files{writeln!(sums,"{}  {}",hash(&fs::read(p).unwrap()),p.strip_prefix(out).unwrap().display()).unwrap();}fs::write(out.join("SHA256SUMS"),sums).unwrap();println!("{}",json!({"published_files":files.len()+1,"publication":record}));}
